package org.sleepwell.app;
import android.content.*;
import android.os.Build;
import androidx.test.platform.app.InstrumentationRegistry;
import androidx.test.uiautomator.UiDevice;
import org.junit.*;
import java.time.*;
import java.util.*;
import static org.junit.Assert.*;
/** Real private persistence, fake scheduling/launch/stop. Never creates sensors or a service. */
public class RecurringTrackingTest {
    final Context c=InstrumentationRegistry.getInstrumentation().getTargetContext();Fake owner;
    @Before public void before()throws Exception{assertEquals("true",InstrumentationRegistry.getArguments().getString("ciReview"));assertTrue(Build.HARDWARE.contains("ranchu")||Build.HARDWARE.contains("goldfish"));assertEquals("1",UiDevice.getInstance(InstrumentationRegistry.getInstrumentation()).executeShellCommand("getprop ro.kernel.qemu").trim());assertFalse(TrackingService.running);assertFalse(AlarmService.active);assertFalse(Prefs.flag(c,"ringing"));assertFalse(Prefs.flag(c,"tracking"));owner=new Fake(c);}
    @After public void after(){assertTrue(owner.p.edit().clear().commit());assertTrue(c.deleteSharedPreferences(owner.name));assertFalse(TrackingService.running);assertFalse(AlarmService.active);}
    static final class Fake implements RecurringTracking.Port {
        final String name="recurring-test-"+UUID.randomUUID();final SharedPreferences p;long now=LocalDateTime.parse("2026-10-24T21:00").atZone(ZoneId.of("Asia/Riyadh")).toInstant().toEpochMilli();ZoneId zone=ZoneId.of("Asia/Riyadh");boolean exact=true,notifications=true,movement=true,charging=true,occupied,owns,failSchedule,failLaunch;int schedules,launches,stops,cancels;String token,stopped;long at;RecurringTracking.Run launched;
        Fake(Context c){p=c.getSharedPreferences(name,0);}public SharedPreferences preferences(Context c){return p;}public long now(){return now;}public ZoneId zone(){return zone;}public boolean exact(Context c){return exact;}public boolean notifications(Context c){return notifications;}public boolean movement(Context c){return movement;}public boolean charging(Context c){return charging;}public boolean occupied(Context c){return occupied;}public boolean ownsRun(Context c,String token){return owns;}
        public void schedule(Context c,long at,String token){schedules++;if(failSchedule)throw new SecurityException("Exact timing permission changed.");this.at=at;this.token=token;}public void cancel(Context c,String token){cancels++;}public void launch(Context c,RecurringTracking.Run run){launches++;if(failLaunch)throw new IllegalStateException("Foreground start was blocked.");launched=run;}public void stopOwned(Context c,String token){stops++;stopped=token;}
        RecurringTracking.Config enable(Context c,boolean stillness,boolean charge){return RecurringTracking.save(c,this,new RecurringTracking.Config(0,true,1350,stillness,charge),0);}
        void due(Context c){now=at;RecurringTracking.receive(c,this,token);}
    }
    @Test public void exportedReconciliationRejectsNullAndUntrustedActionsBeforeAnyPortAccess(){RecurringTracking.Port prior=RecurringTracking.port;try{RecurringTracking.port=owner;RecurringTrackingBootReceiver receiver=new RecurringTrackingBootReceiver();receiver.onReceive(c,null);receiver.onReceive(c,new Intent());receiver.onReceive(c,new Intent("org.example.FORGED_BOOT"));new RecurringTrackingReceiver().onReceive(c,new Intent(RecurringTracking.ACTION));assertEquals(0,owner.schedules);assertEquals(0,owner.launches);assertTrue(owner.p.getAll().isEmpty());}finally{RecurringTracking.port=prior;}}
    @Test public void productionRejectsOffMainAdmissionBeforePreferencesOrEffects(){assertNotEquals(android.os.Looper.getMainLooper(),android.os.Looper.myLooper());Map<String,?> before=Prefs.of(c).getAll();for(Runnable call:new Runnable[]{()->RecurringTracking.save(c,RecurringTracking.PLATFORM,new RecurringTracking.Config(0,true,1350,false,false),0),()->RecurringTracking.receive(c,RecurringTracking.PLATFORM,"none"),()->RecurringTracking.reconcile(c,RecurringTracking.PLATFORM),()->RecurringTracking.recover(c,RecurringTracking.PLATFORM,false),()->RecurringTracking.accept(c,RecurringTracking.PLATFORM,new Intent()),()->RecurringTracking.ended(c,RecurringTracking.PLATFORM,"none","none"),()->RecurringTracking.occupied(c,RecurringTracking.PLATFORM,"none")}){try{call.run();fail();}catch(IllegalStateException expected){assertTrue(expected.getMessage().contains("main thread"));}}assertEquals(before,Prefs.of(c).getAll());}
    @Test public void occupiedManualTakeoverClearsOnlyPendingClaimAndAbaCannotReuseItsRequest(){RecurringTracking.Config first=owner.enable(c,false,false);owner.due(c);Intent stale=owner.launched.intent(c);String token=owner.launched.token;RecurringTracking.occupied(c,owner,"wrong-owner");assertEquals(token,owner.p.getString("run",""));RecurringTracking.occupied(c,owner,token);assertEquals("",owner.p.getString("run",""));assertTrue(owner.p.getString("status","").contains("another tracking session"));assertEquals(0,owner.stops);RecurringTracking.save(c,owner,new RecurringTracking.Config(1,false,1350,false,false),1);RecurringTracking.save(c,owner,new RecurringTracking.Config(2,true,1350,false,false),2);assertNull(RecurringTracking.accept(c,owner,stale));assertEquals(0,owner.stops);owner.due(c);RecurringTracking.Run accepted=RecurringTracking.accept(c,owner,owner.launched.intent(c));assertNotNull(accepted);RecurringTracking.occupied(c,owner,accepted.token);assertEquals("STARTED",owner.p.getString("runState",""));assertNull(RecurringTracking.accept(c,owner,stale));}
    @Test public void persistedOccurrenceClaimsOnceAndServiceSanitizesUntrustedCaptureExtras(){owner.enable(c,true,false);String first=owner.token;long at=owner.at;owner.due(c);assertEquals(1,owner.launches);assertNotEquals(first,owner.token);assertTrue(owner.at>at);RecurringTracking.receive(c,owner,first);assertEquals(1,owner.launches);Intent forged=owner.launched.intent(c).putExtra("recordSounds",true).putExtra("keepClips",true).putExtra("mode","MANUAL");RecurringTracking.Run accepted=RecurringTracking.accept(c,owner,forged);assertNotNull(accepted);assertTrue(accepted.stillness);Intent trusted=accepted.intent(c);assertFalse(trusted.getBooleanExtra("recordSounds",true));assertFalse(trusted.getBooleanExtra("keepClips",true));assertEquals("STILLNESS",trusted.getStringExtra("mode"));assertNull(RecurringTracking.accept(c,owner,forged));assertEquals("2026-10-24",owner.p.getString("lastDate",""));}
    @Test public void enabledEditsPreserveAdmittedTonightRunButFenceUnadmittedClaim(){owner.enable(c,true,false);owner.due(c);RecurringTracking.Run admitted=RecurringTracking.accept(c,owner,owner.launched.intent(c));assertNotNull(admitted);RecurringTracking.save(c,owner,new RecurringTracking.Config(1,true,1320,false,true),1);assertEquals(0,owner.stops);assertEquals(admitted.token,owner.p.getString("run",""));assertEquals("STARTED",owner.p.getString("runState",""));RecurringTracking.ended(c,owner,admitted.token,"Tonight complete");assertEquals("Tonight complete",owner.p.getString("status",""));owner.due(c);Intent queued=owner.launched.intent(c);RecurringTracking.save(c,owner,new RecurringTracking.Config(2,true,1350,false,false),2);assertNull(RecurringTracking.accept(c,owner,queued));assertEquals("",owner.p.getString("run",""));}
    @Test public void chargeAndOccupiedSkipsPersistAndNeverLaunchLaterOnPlug(){owner.enable(c,false,true);owner.charging=false;owner.due(c);assertEquals(0,owner.launches);assertTrue(owner.p.getString("status","").contains("not charging"));String tomorrow=owner.token;owner.charging=true;RecurringTracking.receive(c,owner,tomorrow);assertEquals(0,owner.launches);owner.occupied=true;owner.now=owner.at;RecurringTracking.receive(c,owner,tomorrow);assertEquals(0,owner.launches);assertTrue(owner.p.getString("status","").contains("already active"));}
    @Test public void disableRevokesOnlyOwnedRunAndRejectsStaleDraftAndAbaDelivery(){RecurringTracking.Config saved=owner.enable(c,false,false);String first=owner.token;owner.due(c);String run=owner.launched.token;RecurringTracking.save(c,owner,new RecurringTracking.Config(saved.revision,false,1350,false,false),saved.revision);assertEquals(run,owner.stopped);assertEquals(1,owner.stops);assertNull(RecurringTracking.accept(c,owner,owner.launched.intent(c)));RecurringTracking.receive(c,owner,first);assertEquals(1,owner.launches);try{RecurringTracking.save(c,owner,new RecurringTracking.Config(0,true,1350,false,false),0);fail();}catch(IllegalStateException expected){}assertFalse(RecurringTracking.load(owner.p,0).enabled);}
    @Test public void permissionRevocationLateDeliveryAndLauncherFailureHaveNoUnownedRetry(){owner.enable(c,false,false);owner.notifications=false;owner.due(c);assertEquals(0,owner.launches);assertTrue(owner.p.getString("status","").contains("notifications"));owner.notifications=true;RecurringTracking.reconcile(c,owner);owner.now=owner.at+RecurringNight.GRACE+1;String late=owner.token;RecurringTracking.receive(c,owner,late);assertEquals(0,owner.launches);assertTrue(owner.p.getString("status","").contains("delayed"));owner.failLaunch=true;owner.now=owner.at;RecurringTracking.receive(c,owner,owner.token);assertEquals(1,owner.launches);assertEquals("",owner.p.getString("run",""));assertTrue(owner.p.getString("status","").contains("blocked"));}
    @Test public void reconciliationIsFutureOnlyAndSchedulerFailureIsVisible(){owner.enable(c,false,false);String pending=owner.token;owner.now=owner.at+3600000;RecurringTracking.reconcile(c,owner);assertEquals(0,owner.launches);assertNotEquals(pending,owner.token);assertTrue(owner.at>owner.now);owner.failSchedule=true;RecurringTracking.reconcile(c,owner);assertEquals("",owner.p.getString("pending",""));assertTrue(owner.p.getString("scheduleStatus","").contains("permission changed"));owner.exact=false;try{RecurringTracking.save(c,owner,new RecurringTracking.Config(1,true,1350,false,false),1);fail();}catch(IllegalStateException expected){assertTrue(expected.getMessage().contains("exact alarms"));}assertEquals(0,owner.launches);}
    @Test public void recoveryNeverBackfillsDeadClaimsAndPreservesLiveOwnedRun(){owner.enable(c,false,false);owner.due(c);RecurringTracking.Run admitted=RecurringTracking.accept(c,owner,owner.launched.intent(c));assertNotNull(admitted);owner.owns=true;RecurringTracking.recover(c,owner,false);assertEquals(admitted.token,owner.p.getString("run",""));owner.owns=false;RecurringTracking.recover(c,owner,false);assertEquals("",owner.p.getString("run",""));assertTrue(owner.p.getString("status","").contains("will not be replayed"));assertEquals(1,owner.launches);owner.due(c);String queued=owner.launched.token;RecurringTracking.recover(c,owner,false);assertEquals(queued,owner.p.getString("run",""));RecurringTracking.recover(c,owner,true);assertEquals("",owner.p.getString("run",""));assertEquals(2,owner.launches);assertEquals(0,owner.stops);}
    @Test public void timeZoneChangeRejectsOldOccurrenceAndReconcilesWithoutStarting(){owner.enable(c,false,false);String old=owner.token;owner.now=owner.at;owner.zone=ZoneId.of("America/New_York");RecurringTracking.receive(c,owner,old);assertEquals(0,owner.launches);assertNotEquals(old,owner.token);assertTrue(owner.at>owner.now);assertEquals("America/New_York",owner.p.getString("pendingZone",""));assertTrue(owner.p.getString("status","").contains("Time zone changed"));}
    @Test public void serviceRechecksPermissionsOccupancyRevisionAndExpiryBeforeAcceptance(){owner.enable(c,false,false);owner.due(c);Intent request=owner.launched.intent(c);owner.movement=false;assertNull(RecurringTracking.accept(c,owner,request));assertEquals("",owner.p.getString("run",""));assertTrue(owner.p.getString("status","").contains("sensor"));owner.movement=true;owner.due(c);owner.now+=RecurringNight.GRACE+1;assertNull(RecurringTracking.accept(c,owner,owner.launched.intent(c)));assertEquals("",owner.p.getString("run",""));assertTrue(owner.p.getString("status","").contains("outside its allowed"));assertEquals(2,owner.launches);}
}
